def is_difference_of_squares(n):
    if n < 0:
        return False
    factors = [(i, n//i) for i in range(1, int(n**0.5)+1) if n % i == 0]
    for factor in factors:
        a, b = factor
        if (a + b) % 2 == 0 and (b - a) % 2 == 0:
            return True
    return False

