def count_sequences(m, n):
    if n == 1:
        return m
    if m < 2:
        return 0
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(1, m + 1):
        dp[1][i] = i
    for i in range(2, n + 1):
        for j in range(2, m + 1):
            for k in range(j // 2, j + 1):
                dp[i][j] += dp[i - 1][k]
    return sum(dp[n][i] for i in range(1, m + 1))

